#include "inference.h"
#include "model_data.h"
#include "model_weights.h"
#include <math.h>

// ── Weights (generated by training/train.py → model_weights.h) ───────────────
// `const` at namespace scope → placed in flash (.rodata), not RAM.
// Kernels are row-major [in][out], exactly as Keras stores Dense kernels.

namespace {

// Encoder: 4 → 8 → 2
const float W_enc1[4][8] = WEIGHTS_ENC1;
const float B_enc1[8]    = BIAS_ENC1;
const float W_enc2[8][2] = WEIGHTS_ENC2;
const float B_enc2[2]    = BIAS_ENC2;

// Decoder: 2 → 8 → 4
const float W_dec1[2][8] = WEIGHTS_DEC1;
const float B_dec1[8]    = BIAS_DEC1;
const float W_dec2[8][4] = WEIGHTS_DEC2;
const float B_dec2[4]    = BIAS_DEC2;

// ── Activation functions (single-precision: the ESP32 FPU has no double) ────
inline float relu(float x)    { return x > 0.0f ? x : 0.0f; }
inline float sigmoid(float x) { return 1.0f / (1.0f + expf(-x)); }

enum Activation { RELU, SIGMOID };

// ── Dense layer ───────────────────────────────────────────────────────────────
// Sizes are template parameters: the compiler checks every layer's shape
// against its weight array and can fully unroll the loops.
template <int IN, int OUT, Activation ACT>
inline void dense(const float (&in)[IN],
                  const float (&W)[IN][OUT], const float (&B)[OUT],
                  float (&out)[OUT])
{
    for (int j = 0; j < OUT; ++j) {
        float sum = B[j];
        for (int i = 0; i < IN; ++i)
            sum += in[i] * W[i][j];
        out[j] = (ACT == RELU) ? relu(sum) : sigmoid(sum);
    }
}

} // namespace

// ── InferenceEngine ───────────────────────────────────────────────────────────

float InferenceEngine::threshold() { return ANOMALY_THRESHOLD; }

InferenceResult InferenceEngine::run(const Features& f) const {
    InferenceResult r;

    // Normalize: multiply by precomputed 1/range (no division on the device)
    const float raw[4] = {f.filtered_cm, f.jitter, f.rate_of_change, f.variance};
    for (int i = 0; i < 4; ++i)
        r.input[i] = (raw[i] - NORM_MIN[i]) * NORM_SCALE[i];

    // Encoder
    float h1[8], latent[2];
    dense<4, 8, RELU>(r.input, W_enc1, B_enc1, h1);
    dense<8, 2, RELU>(h1,      W_enc2, B_enc2, latent);

    // Decoder
    float h2[8];
    dense<2, 8, RELU>   (latent, W_dec1, B_dec1, h2);
    dense<8, 4, SIGMOID>(h2,     W_dec2, B_dec2, r.reconstructed);

    float sum = 0.0f;
    for (int i = 0; i < 4; ++i) {
        const float d = r.input[i] - r.reconstructed[i];
        sum += d * d;
    }
    r.reconstruction_mse = sum / 4.0f;
    r.is_anomaly         = r.reconstruction_mse > ANOMALY_THRESHOLD;
    return r;
}

// ── AlarmFilter ───────────────────────────────────────────────────────────────

bool AlarmFilter::update(bool is_anomaly) {
    if (is_anomaly) {
        if (over_ < 255) over_++;
        under_ = 0;
    } else {
        if (under_ < 255) under_++;
        over_ = 0;
    }
    if (!active_ && over_ >= MODEL_ALARM_ON_COUNT)       active_ = true;
    else if (active_ && under_ >= MODEL_ALARM_OFF_COUNT) active_ = false;
    return active_;
}
